                            selectTarget: 2,
                            postAi: () => true,
                            contentBefore() {
                                if (!targets.length) return;
                                var map = {};
                                event.parent.customArgs.default.tx_shiji_tjym_map = map;
                                var average = 0;
                                for (var target of targets) {
                                    var hs = target.countCards('h');
                                    map[target.playerid] = hs;
                                    average += hs;
                                }
                                map.average = average / targets.length;
                            },
                            content() {
                                var map = event.tx_shiji_tjym_map,
                                    num1 = map.average,
                                    num2 = map[target.playerid];
                                if (typeof num2 != 'number') num2 = target.countCards('h');
                                if (num2 > num1) target.chooseToDiscard('he', true);
                                else if (num2 < num1) target.draw();
                            },
                            contentAfter() {
                                'step 0';
                                if (!player.isIn() || targets.length < 2) {
                                    event.finish();
                                    return;
                                }
                                var num = targets[0].countCards('h');
                                for (let i = 1; i < targets.length; i++) {
                                    if (targets[i].countCards('h') != num) {
                                        event.finish();
                                        return;
                                    }
                                }
                                var cards = [];
                                game.getGlobalHistory('cardMove', function (evt) {
                                    if (evt.name == 'lose' && evt.type == 'discard' && evt.getParent(3).card == card) cards.addArray(evt.cards);
                                });
                                cards = cards.filterInD('d');
                                if (cards.length) {
                                    event.tx_shiji_tjym_cards = cards;
                                    player.chooseTarget('是否回复1点体力并令一名角色获得' + get.translation(cards) + '？').set('ai', function (target) {
                                        var evt = _status.event.parent;
                                        return get.attitude(evt.player, target) * get.value(evt.tx_shiji_tjym_cards, target) * (target.hasSkillTag('nogain') ? 0.1 : 1);
                                    });
                                } else event.finish();
                                ('step 1');
                                if (result.bool) {
                                    var target = result.targets[0];
                                    player.line(target, 'thunder');
                                    player.recover();
                                    target.gain(event.tx_shiji_tjym_cards, 'gain2');
                                }
                            },
                            ai: {
                                order: 6.1,
                                basic: {
                                    useful: 4,
                                    value: 3,
                                },
                                result: {
                                    target(player, target, card, isLink) {
                                        var targets = [];
                                        if (ui.selected.targets.length) targets.addArray(ui.selected.targets);
                                        var evt = _status.event.getParent('useCard');
                                        if (evt && evt.card == card) targets.addArray(evt.targets);
                                        if (evt && evt.card == card && evt.customArgs && evt.customArgs.tx_shiji_tjym_map) {
                                            var map = evt.customArgs.tx_shiji_tjym_map,
                                                num1 = map.average,
                                                num2 = map[target.playerid];
                                            if (typeof num2 != 'number') num2 = target.countCards('h');
                                            if (num2 > num1) {
                                                if (
                                                    target.countCards('e', function (card) {
                                                        return get.value(card) <= 0;
                                                    })
                                                )
                                                    return 1;
                                                return -1;
                                            }
                                            if (num2 < num1) return 1;
                                            return 0;
                                        }
                                        var cards = [card];
                                        if (card.cards) cards.addArray(card.cards);
                                        var fh = function (card) {
                                            return !cards.includes(card);
                                        };
                                        if (!targets.length) {
                                            if (get.attitude(player, target) < 0) {
                                                if (
                                                    target.countCards('e', function (card) {
                                                        return get.value(card, target) <= 0;
                                                    })
                                                )
                                                    return 1;
                                                if (
                                                    game.hasPlayer(function (current) {
                                                        return current.countCards('h', fh) == target.countCards('h', fh) - 2;
                                                    })
                                                )
                                                    return -2;
                                                if (
                                                    game.hasPlayer(function (current) {
                                                        return current.countCards('h', fh) < target.countCards('h', fh);
                                                    })
                                                )
                                                    return -1;
                                            }
                                            if (
                                                target.countCards('e', function (card) {
                                                    return get.value(card, target) <= 0;
                                                }) &&
                                                game.hasPlayer(function (current) {
                                                    return current.countCards('h', fh) < target.countCards('h', fh);
                                                })
                                            )
                                                return 1;
                                            return 0;
                                        }
                                        var average = 0;
                                        for (const i of targets) average += i.countCards('h', fh);
                                        if (!targets.includes(target)) {
                                            var th = target.countCards('h', fh);
                                            average += th;
                                            average /= targets.length + 1;
                                            if (th == average) return 0;
                                            if (th < average) return th == average - 1 ? 2 : 1;
                                            if (th > average) {
                                                if (
                                                    target.countCards('e', function (card) {
                                                        return get.value(card) <= 0;
                                                    })
                                                )
                                                    return 1;
                                                return -0.5;
                                            }
                                            return 0;
                                        }
                                        average /= targets.length;
                                        if (th < average) return 1;
                                        if (th > average) {
                                            if (
                                                target.countCards('e', function (card) {
                                                    return get.value(card) <= 0;
                                                })
                                            )
                                                return 1;
                                            return -1;
                                        }
                                        return 0;
                                    },
                                },
                            },
