                        tx_fh_beige: {
                            audio: 'olbeige',
                            inherit: 'olbeige',
                            content() {
                                'step 0';
                                event.target = trigger.player;
                                event.source = trigger.source;
                                trigger.player.judge();
                                ('step 1');
                                event.judgeResult = get.copy(result);
                                var str = '是否弃置一张牌',
                                    strt = get.translation(target),
                                    strs = get.translation(source),
                                    goon = 0;
                                switch (result.suit) {
                                    case 'heart':
                                        if (target.isIn() && target.isDamaged()) {
                                            str += ',令' + strt + '回复' + get.cnNumber(trigger.num) + '点体力';
                                            goon = get.recoverEffect(target, player, player);
                                        }
                                        break;
                                    case 'diamond':
                                        if (target.isIn()) {
                                            str += ',令' + strt + '摸三张牌';
                                            goon = 2 * get.effect(target, { name: 'draw' }, player, player);
                                        }
                                        break;
                                    case 'spade':
                                        if (source && source.isIn()) {
                                            str += ',令' + strs + '翻' + (source.isTurnedOver() ? '回正' : '') + '面';
                                            goon = get.attitude(player, source) * (source.isTurnedOver() ? 2 : -2);
                                        }
                                        break;
                                    case 'club':
                                        if (source && source.isIn()) {
                                            str += ',令' + strs + '弃置两张牌';
                                            var cards = source
                                                .getCards('he')
                                                .sort(function (a, b) {
                                                    return get.value(a, source) - get.value(b, source);
                                                })
                                                .slice(0, 2);
                                            for (const i of cards) goon += get.value(i, source);
                                            goon *= -get.sgn(get.attitude(player, source));
                                        }
                                        break;
                                }
                                str += '？';
                                var str2 = '若弃置点数为' + get.strNumber(result.number) + '的牌则收回自己弃置的牌';
                                if (get.position(result.card, true) == 'd') {
                                    str2 += ';若弃置花色为' + get.translation(result.suit) + '的牌则获得' + get.translation(result.card);
                                }
                                player
                                    .chooseToDiscard('he', str, str2)
                                    .set('goon', goon)
                                    .set('ai', function (card) {
                                        var goon = _status.event.goon;
                                        var player = _status.event.player;
                                        var result = _status.event.parent.judgeResult;
                                        var eff = Math.min(7, goon);
                                        if (eff <= 0) return 0;
                                        if (card.suit == result.suit) eff += get.value(result.card, player);
                                        if (card.number == result.number) return eff;
                                        return eff - get.value(card);
                                    });
                                ('step 2');
                                if (result.bool) {
                                    event.card = result.cards[0];
                                    switch (event.judgeResult.suit) {
                                        case 'heart':
                                            if (target.isIn() && target.isDamaged()) trigger.player.recover(trigger.num);
                                            break;
                                        case 'diamond':
                                            if (target.isIn()) trigger.player.draw(3);
                                            break;
                                        case 'club':
                                            if (source && source.isIn() && source.countCards('he')) trigger.source.chooseToDiscard('he', 2, true);
                                            break;
                                        case 'spade':
                                            if (source && source.isIn()) trigger.source.turnOver();
                                            break;
                                    }
                                } else event.finish();
                                ('step 3');
                                var gains = [];
                                if (get.position(event.judgeResult.card, true) == 'd' && card.suit == event.judgeResult.suit) gains.push(event.judgeResult.card);
                                if (get.position(card, true) == 'd' && card.number == event.judgeResult.number) gains.push(card);
                                if (gains.length) player.gain(gains, 'gain2');
                            },
                        },
